def merge(intervals):
    """Return the merged intervals, sorted by start.

    Each interval is a [start, end] pair. Intervals that overlap or touch
    are joined into one interval. The input list is not changed.
    """
    if not intervals:
        return []

    ordered = sorted(intervals, key=lambda interval: interval[0])
    merged = [[ordered[0][0], ordered[0][1]]]

    for start, end in ordered[1:]:
        last = merged[-1]
        if start <= last[1]:
            if end > last[1]:
                last[1] = end
        else:
            merged.append([start, end])

    return merged
